    Case("LLM-BB-57", "basic", "Inline code adjacent to text", "a`b`c", "<p>a<code>b</code>c</p>"),
    Case("LLM-BB-58", "basic", "Heading with trailing spaces", "# Title   ", "<h1>Title</h1>"),
    Case("LLM-BB-59", "basic", "Emphasis nested inside strong", "**a *b* c**", "<p><strong>a <em>b</em> c</strong></p>"),
    Case("LLM-BB-60", "basic", "Paragraph with mixed inline elements", "Start **bold** then [link](https://example.com) and `code`.", "<p>Start <strong>bold</strong> then <a href=\"https://example.com\">link</a> and <code>code</code>.</p>"),
    Case("LLM-BB-61", "html", "Raw HTML block with script tag to exercise block HTML parsing", "<script>\nconsole.log('x')\n</script>", "<script>\nconsole.log('x')\n</script>"),
    Case("LLM-BB-62", "html", "Raw HTML block with tag content followed by Markdown text", "<style>\nbody { color: red; }\n</style>\n\nParagraph after HTML.", "<style>\nbody { color: red; }\n</style><p>Paragraph after HTML.</p>"),
